{"cards": [{"node_code": "N_783b33c89b6fcd2e", "definition": "研究沥青路面体系中各结构层（面层、基层、底基层等）的材料选择、厚度配置及层间组合方式，旨在构建满足力学与功能要求的整体结构。", "boundary": "本节点聚焦于“结构层如何组合”这一设计核心，涵盖纯沥青结构、沥青与混凝土复合结构及特殊组合形式。边界在于区分“结构组合方案”与“单层材料性能”或“具体计算过程”：材料本身的物理力学指标归入性能节点，厚度计算与力学分析归入结构设计节点。包含对复合式路面中沥青层与混凝土层协同作用的组合逻辑研究。", "includes": ["沥青路面各结构层（面、基、底、垫）的材料类型与厚度配置方案", "复合式路面（如沥青+混凝土）的结构层序、界面处理及组合原理", "不同交通等级与环境条件下路面结构组合的选型原则"], "excludes": ["单一沥青混合料或基层材料的物理力学性能测试与指标（归入性能）", "基于弹性层状体系理论的具体厚度计算与应力应变分析（归入结构设计）"], "sibling_distinctions": [{"other_code": "N_2165be3e0e2c54f2", "rule": "本节点关注结构层的“配置与组合逻辑”（用什么材料、怎么排布）；兄弟节点关注基于力学模型的“计算与验证”（算多厚、应力是否达标）。"}, {"other_code": "N_bdcb15e2180b311d", "rule": "本节点关注结构整体的“构造组成”；兄弟节点关注组成材料或结构整体的“物理力学指标”（如强度、模量、抗滑性）。"}], "cross_boundary_rule": "当研究涉及特定结构组合下的力学响应时，组合方案本身归入本节点，具体的力学计算过程归入结构设计节点。"}, {"node_code": "N_ad64b372f77e39de", "definition": "研究沥青路面在长期交通荷载、环境因素及材料老化共同作用下的性能衰减规律、寿命预测方法及耐久性评价指标体系。", "boundary": "本节点聚焦于“时间维度”上的性能保持能力与寿命评估。边界在于区分“耐久性评价”与“即时性能”或“病害诊断”：即时力学指标归入性能节点，已发生病害的识别与处治归入路面性能、病害与耐久评价（父级兄弟节点，若存在）或养护节点。本节点侧重设计阶段的寿命预测、老化机理及耐久性指标（如抗老化性、疲劳寿命）的确定。", "includes": ["沥青混合料及路面结构的老化机理、疲劳寿命预测模型", "耐久性评价指标体系（如抗热老化、抗冻融、抗水损害能力）", "全寿命周期内的性能衰减规律及耐久性设计方法"], "excludes": ["路面建成后的实时性能监测、病害识别与处治技术（归入路面性能、病害与耐久评价或养护工程）", "单一时刻的力学性能指标测试（如抗压强度、弹性模量，归入性能）"], "sibling_distinctions": [{"other_code": "N_bdcb15e2180b311d", "rule": "本节点关注“随时间变化”的性能保持与寿命（动态/长期）；兄弟节点关注“特定状态”下的物理力学指标（静态/瞬时）。"}, {"other_code": "N_2165be3e0e2c54f2", "rule": "本节点关注设计阶段的寿命预测与耐久性指标设定；兄弟节点关注满足力学要求（如不破坏、不超限）的结构计算。"}], "cross_boundary_rule": "当涉及耐久性对结构设计的影响时，耐久性指标（如设计寿命、老化系数）的确定归入本节点，将其作为参数输入结构计算的过程归入结构设计节点。"}, {"node_code": "N_bdcb15e2180b311d", "definition": "研究沥青路面结构及其组成材料在特定状态下的物理力学性能指标，包括强度、模量、抗滑性、水稳定性及温度敏感性等。", "boundary": "本节点聚焦于“材料或结构在特定条件下的力学与物理响应”。边界在于区分“性能指标”与“结构组合”或“耐久评价”：结构层的配置归入结构组合节点，长期老化与寿命归入耐久评价节点。本节点涵盖沥青混合料、基层材料以及路面结构整体的力学参数（如动态模量、劲度模量）及功能性能（如抗滑、抗车辙能力）的测试与评价。", "includes": ["沥青混合料及基层材料的物理力学指标（强度、模量、密度、空隙率等）", "路面结构的功能性能（抗滑性、抗车辙性、水稳定性、低温抗裂性）", "性能测试方法、评价指标及性能与结构响应的关系分析"], "excludes": ["结构层的材料选择与厚度配置方案（归入路面结构组合）", "长期老化机理、疲劳寿命预测及全寿命周期性能衰减（归入耐久评价）"], "sibling_distinctions": [{"other_code": "N_783b33c89b6fcd2e", "rule": "本节点关注“材料/结构有什么性能”（指标与测试）；兄弟节点关注“结构由什么组成”（配置与组合）。"}, {"other_code": "N_ad64b372f77e39de", "rule": "本节点关注“当前/特定状态”的性能表现；兄弟节点关注“长期/时间累积”后的性能保持与寿命。"}], "cross_boundary_rule": "当性能指标用于结构设计时，指标的获取与定义归入本节点，指标在结构计算中的应用归入结构设计节点。"}]}
